import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export function ShowcaseProviders({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) {
  return (
    <CSPProvider disableStyleElements>
      <OverlayProvider>
        {children}
        {toast && <Toaster />}
      </OverlayProvider>
    </CSPProvider>
  );
}

export function ShowcaseSurface({ children }: { children?: ReactNode }) {
  return (
    <div
      data-slot="component-preview"
      className="relative isolate mx-auto flex min-h-64 w-full min-w-0 max-w-3xl items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center"
    >
      {children}
    </div>
  );
}

import { Separator } from "@/registry/erbium/ui/separator";

export default function SeparatorDemo() {
  return (
    <div>
      <div className="space-y-1">
        <h4 className="text-subtitle">Radix Primitives</h4>
        <p className="text-caption text-muted-foreground">An open-source UI component library.</p>
      </div>
      <Separator className="my-4" />
      <div className="flex h-5 items-center space-x-4 text-caption">
        <div>Blog</div>
        <Separator orientation="vertical" />
        <div>Docs</div>
        <Separator orientation="vertical" />
        <div>Source</div>
      </div>
    </div>
  );
}

import { Separator } from "@/registry/erbium/ui/separator";

export function SeparatorVertical() {
  return (
    <div className="flex h-5 items-center gap-group text-caption">
      <div>Blog</div>
      <Separator orientation="vertical" />
      <div>Docs</div>
      <Separator orientation="vertical" />
      <div>Source</div>
    </div>
  );
}

// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import { Separator } from "@/registry/erbium/ui/separator";

import PlaygroundExample from "./variants/playground";

const PlaygroundSource = "import { Separator } from \"@/registry/erbium/ui/separator\";\nimport type * as React from \"react\";\n\nconst Example = (args: React.ComponentProps<typeof Separator>) => (\n  <div className=\"flex h-28 w-72 flex-col items-center justify-center\">\n    <Separator\n      {...args}\n      className={\n        args.orientation === \"vertical\"\n          ? `h-full ${typeof args.className === \"string\" ? args.className : \"\"}`\n          : `w-full ${typeof args.className === \"string\" ? args.className : \"\"}`\n      }\n    />\n  </div>\n);\n\nexport default Example;\n";

import OverviewExample from "./variants/overview";

const OverviewSource = "import Demo from \"../examples/separator-demo\";\n\nconst Example = () => (\n  <div className=\"w-full min-w-72 max-w-2xl p-4\">\n    <Demo />\n  </div>\n);\n\nexport default Example;\n";

import VerticalExample from "./variants/vertical";

const VerticalSource = "import { SeparatorVertical } from \"../examples/separator-vertical\";\n\nconst Example = () => <SeparatorVertical />;\n\nexport default Example;\n";

import LabeledExample from "./variants/labeled";

const LabeledSource = "import { Separator } from \"@/registry/erbium/ui/separator\";\n\nconst Example = () => (\n  <div className=\"w-72 rounded-lg surface-panel p-4\">\n    <Separator className=\"text-metadata text-muted-foreground\">or</Separator>\n  </div>\n);\n\nexport default Example;\n";

import FullWidthExample from "./variants/full-width";

const FullWidthSource = "import { Separator } from \"@/registry/erbium/ui/separator\";\n\nconst Example = () => (\n  <div className=\"grid w-72 gap-section\">\n    <div className=\"overflow-hidden rounded-lg surface-panel py-3\">\n      <div className=\"px-3 pb-3 text-caption\">Card header</div>\n      <Separator />\n      <div className=\"separator-inset grid gap-3 p-3 text-caption text-muted-foreground\">\n        Card content\n        <Separator />\n        Inset content divider\n      </div>\n    </div>\n    <div className=\"grid gap-3 text-caption text-muted-foreground\">\n      Canvas\n      <Separator />\n      <Separator variant=\"full\" />\n    </div>\n  </div>\n);\n\nexport default Example;\n";

import OnSurfacesExample from "./variants/on-surfaces";

const OnSurfacesSource = "import { Separator } from \"@/registry/erbium/ui/separator\";\nimport { surfaceSamples } from \"../helpers\";\n\nconst Example = () => (\n  <div className=\"grid w-160 max-w-[calc(100vw-2rem)] grid-cols-2 gap-3 p-4 sm:grid-cols-3\">\n    {surfaceSamples.map(([name, surface]) => (\n      <div\n        key={name}\n        className={`flex min-h-24 flex-col justify-center gap-related rounded-lg border border-transparent p-3 ${surface}`}\n      >\n        <span className=\"text-metadata font-medium\">{name}</span>\n        <Separator />\n        <Separator className=\"text-metadata\">or</Separator>\n      </div>\n    ))}\n  </div>\n);\n\nexport default Example;\n";

import MenuExample from "./variants/menu";

const MenuSource = "import { SeparatorMenu } from \"../examples/separator-menu\";\n\nconst Example = () => <SeparatorMenu />;\n\nexport default Example;\n";

import ListExample from "./variants/list";

const ListSource = "import { SeparatorList } from \"../examples/separator-list\";\n\nconst Example = () => (\n  <div className=\"w-72 max-w-[calc(100vw-2rem)]\">\n    <SeparatorList />\n  </div>\n);\n\nexport default Example;\n";

import MarginSizingExample from "./variants/margin-sizing";

const MarginSizingSource = "import { Separator } from \"@/registry/erbium/ui/separator\";\n\nconst Example = () => (\n  <div className=\"grid gap-section\">\n    {([\"ltr\", \"rtl\"] as const).map((direction) => (\n      <div key={direction} dir={direction} className=\"grid gap-3\">\n        {([\"block\", \"flex flex-col items-center\", \"grid justify-items-center\"] as const).map(\n          (layout) => (\n            <div\n              key={layout}\n              data-separator-case\n              className={`w-72 gap-related bg-surface-panel p-4 ${layout}`}\n            >\n              <span className=\"text-caption\">\n                {direction}: {layout}\n              </span>\n              <Separator data-inset=\"0\" className=\"-mx-4\" />\n              <Separator data-inset=\"24\" className=\"mx-2\" />\n              <Separator data-inset=\"0\" className=\"-mx-4\">\n                Labeled\n              </Separator>\n            </div>\n          ),\n        )}\n      </div>\n    ))}\n  </div>\n);\n\nexport default Example;\n";

const meta = {
  component: Separator,
  tags: ["autodocs"],
  parameters: {
    layout: "centered",
    docs: {
      description: {
        component: "## Usage\n\nSeparate content visually or semantically.\n\n**Import:** `@/registry/erbium/ui/separator`\n\n## Usage\n\n```tsx\nimport { Separator } from \"@/registry/erbium/ui/separator\";\n```\n\n```tsx\n<Separator />\n```\n\n## Base UI documentation\n\nExplore the underlying primitives and their API reference.\n\n- [Separator](https://base-ui.com/react/components/separator)",
      },
    },
  },
} satisfies Meta<typeof Separator>;

export default { ...meta, title: "Components/Separator",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Playground: StoryObj<typeof Separator> = {
  args: { orientation: "horizontal", className: "" },
  argTypes: {
    orientation: { control: "select", options: ["horizontal", "vertical"] },
    variant: { control: "select", options: [undefined, "full", "inset"] },
  },
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: PlaygroundSource },
    },
  },
  render: PlaygroundExample,
};

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: OverviewSource },
    },
  },
  render: OverviewExample,
};

export const Vertical: Story = {
  parameters: {
    docs: {
      description: { story: "Use `orientation=\"vertical\"` for a vertical separator." },
      source: { code: VerticalSource },
    },
  },
  render: VerticalExample,
};

export const Labeled: Story = {
  parameters: {
    docs: {
      description: { story: "A centered label stays readable while the carved lines fade at the outer edges." },
      source: { code: LabeledSource },
    },
  },
  render: LabeledExample,
};

export const FullWidth: Story = {
  parameters: {
    docs: {
      description: { story: "Without a `variant`, a separator follows its container. On a surface it runs solid to both edges; in padded content (`separator-inset`) and on the canvas it fades. Pass `variant=\"full\"` or `variant=\"inset\"` to choose." },
      source: { code: FullWidthSource },
    },
  },
  render: FullWidthExample,
};

export const OnSurfaces: Story = {
  parameters: {
    docs: {
      description: { story: "The translucent shadow and catchlight are checked across the surface palette in both themes." },
      source: { code: OnSurfacesSource },
    },
  },
  render: OnSurfacesExample,
};

export const Menu: Story = {
  parameters: {
    docs: {
      description: { story: "Vertical separators between menu items with descriptions." },
      source: { code: MenuSource },
    },
  },
  render: MenuExample,
};

export const List: Story = {
  parameters: {
    docs: {
      description: { story: "Horizontal separators between list items." },
      source: { code: ListSource },
    },
  },
  render: ListExample,
};

export const MarginSizing: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: MarginSizingSource },
    },
  },
  render: MarginSizingExample,
};

import { Separator } from "@/registry/erbium/ui/separator";

const Example = () => (
  <div className="w-72 rounded-lg surface-panel p-4">
    <Separator className="text-metadata text-muted-foreground">or</Separator>
  </div>
);

export default Example;

import { SeparatorList } from "../examples/separator-list";

const Example = () => (
  <div className="w-72 max-w-[calc(100vw-2rem)]">
    <SeparatorList />
  </div>
);

export default Example;

import { Separator } from "@/registry/erbium/ui/separator";

const Example = () => (
  <div className="grid gap-section">
    {(["ltr", "rtl"] as const).map((direction) => (
      <div key={direction} dir={direction} className="grid gap-3">
        {(["block", "flex flex-col items-center", "grid justify-items-center"] as const).map(
          (layout) => (
            <div
              key={layout}
              data-separator-case
              className={`w-72 gap-related bg-surface-panel p-4 ${layout}`}
            >
              <span className="text-caption">
                {direction}: {layout}
              </span>
              <Separator data-inset="0" className="-mx-4" />
              <Separator data-inset="24" className="mx-2" />
              <Separator data-inset="0" className="-mx-4">
                Labeled
              </Separator>
            </div>
          ),
        )}
      </div>
    ))}
  </div>
);

export default Example;

import { SeparatorMenu } from "../examples/separator-menu";

const Example = () => <SeparatorMenu />;

export default Example;

import { Separator } from "@/registry/erbium/ui/separator";
import { surfaceSamples } from "../helpers";

const Example = () => (
  <div className="grid w-160 max-w-[calc(100vw-2rem)] grid-cols-2 gap-3 p-4 sm:grid-cols-3">
    {surfaceSamples.map(([name, surface]) => (
      <div
        key={name}
        className={`flex min-h-24 flex-col justify-center gap-related rounded-lg border border-transparent p-3 ${surface}`}
      >
        <span className="text-metadata font-medium">{name}</span>
        <Separator />
        <Separator className="text-metadata">or</Separator>
      </div>
    ))}
  </div>
);

export default Example;

import Demo from "../examples/separator-demo";

const Example = () => (
  <div className="w-full min-w-72 max-w-2xl p-4">
    <Demo />
  </div>
);

export default Example;

import { Separator } from "@/registry/erbium/ui/separator";
import type * as React from "react";

const Example = (args: React.ComponentProps<typeof Separator>) => (
  <div className="flex h-28 w-72 flex-col items-center justify-center">
    <Separator
      {...args}
      className={
        args.orientation === "vertical"
          ? `h-full ${typeof args.className === "string" ? args.className : ""}`
          : `w-full ${typeof args.className === "string" ? args.className : ""}`
      }
    />
  </div>
);

export default Example;

import { SeparatorVertical } from "../examples/separator-vertical";

const Example = () => <SeparatorVertical />;

export default Example;
